{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 도시공원 조례상 공원으로 결정된 날 이후 한 필지를 둘로 나눈 경우, 창고용 가설건축물 점용허가 시 분할한 각 필지에 200㎡씩 합계 400㎡를 지을 수 있는지",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "공원으로 결정한 날 이후에 하나의 필지를 둘 이상의 필지로 분할한 경우에는 분할 후의 필지 수에 관계없이 하나의 필지로 보므로, 분할한 각 필지에 200㎡씩 합계 400㎡를 지을 수 없습니다. 「공간정보의 구축 및 관리 등에 관한 법률」에 따른 필지를 단위로 하여 하나의 필지에 건축할 수 있는 가설건축물의 연면적은 200제곱미터 이내입니다.",
          "b_ids": "도시공원:제10조제1항제3호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
